function renderInvestments(){const rows=Array.isArray(state.investments)?state.investments:[],groups={"Mutual Funds":[],Stocks:[],ETFs:[],Others:[]};rows.forEach(h=>(groups[h.category]||groups.Others).push(h));const total=sum(rows,h=>Number(h.value)||0);$("investmentTotal").textContent=money(total);const ids={"Mutual Funds":["mfValue","mfCount"],Stocks:["stockValue","stockCount"],ETFs:["etfValue","etfCount"],Others:["otherValue","otherCount"]};Object.entries(groups).forEach(([k,a])=>{$(ids[k][0]).textContent=money(sum(a,h=>Number(h.value)||0));$(ids[k][1]).textContent=`${a.length} holdings`;});}
