function categoryIconSvg(t){const c=String(t.category||"").toLowerCase();let p='<path d="M4 12h16M12 4v16"/>';if(/food|dining|restaurant|swiggy|zomato/.test(c))p='<path d="M6 3v8m-3-8v5a3 3 0 0 0 6 0V3M6 11v10m10-18v18m0-18c3 3 3 7 0 10"/>';else if(/grocery|supermarket/.test(c))p='<path d="M3 4h2l2 12h11l3-8H6M9 20h.01M17 20h.01"/>';else if(/fuel|petrol|diesel/.test(c))p='<path d="M5 21V4a2 2 0 0 1 2-2h7a2 2 0 0 1 2 2v17M4 21h13M8 6h5v5H8zM16 8h2l2 3v6a2 2 0 0 1-4 0v-4"/>';else if(/wifi|internet|subscription/.test(c))p='<path d="M2 8a15 15 0 0 1 20 0M5 12a10 10 0 0 1 14 0m-11 4a5 5 0 0 1 8 0m-4 4h.01"/>';else if(t.kind==="Transfer")p='<path d="M3 8h17m-4-4 4 4-4 4M21 16H4m4-4-4 4 4 4"/>';else if(t.kind==="Income")p='<path d="M12 19V5m-6 6 6-6 6 6"/>';else p='<path d="M12 5v14m-6-6 6 6 6-6"/>';return `<svg viewBox="0 0 24 24" aria-hidden="true">${p}</svg>`;}
function txRow(t,actions=false){const color=t.kind==="Income"?"positive":t.kind==="Expense"?"negative":"";return `<div class="list-row transaction-row" data-open-tx="${esc(t.id)}">${actions?`<label class="tx-select"><input type="checkbox" data-select-tx="${esc(t.id)}" ${selectedTransactionIds.has(String(t.id))?"checked":""} aria-label="Select transaction"></label>`:""}<div class="row-icon ${t.kind==="Income"?"income-icon":t.kind==="Expense"?"expense-icon":"transfer-icon"}">${categoryIconSvg(t)}</div><div class="row-main"><strong>${esc(t.category)}</strong><small>${esc(t.note||t.kind)}${t.account?" · "+esc(t.account):""}${t.recurring?" · Recurring":""}</small></div><div class="row-amount ${color}">${t.kind==="Income"?"+":t.kind==="Expense"?"−":""}${money(t.amount)}</div></div>`;}

function bindDeletes(){document.querySelectorAll("[data-delete]").forEach(b=>b.onclick=async()=>{const key={transaction:"transactions",asset:"assets",debt:"liabilities"}[b.dataset.delete];if(!confirm("Delete this record?"))return;state[key]=state[key].filter(x=>x.id!==b.dataset.id);await persist();});}
function budgetCategoryIcon(category){const c=String(category||"").toLowerCase();let path='<circle cx="12" cy="12" r="7"/><path d="M12 8v8m-4-4h8"/>';if(/food|dining|restaurant/.test(c))path='<path d="M6 3v8m-3-8v5a3 3 0 0 0 6 0V3M6 11v10m10-18v18m0-18c3 3 3 7 0 10"/>';else if(/grocer|supermarket/.test(c))path='<path d="M3 4h2l2 12h11l3-8H6M9 20h.01M17 20h.01"/>';else if(/transport|travel|fuel/.test(c))path='<path d="M5 18V6a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2v12M3 18h18M8 8h8v5H8zM8 21h.01M16 21h.01"/>';else if(/utilit|electric|water|bill/.test(c))path='<path d="M13 2 5 13h6l-1 9 9-12h-6z"/>';else if(/subscription|internet/.test(c))path='<path d="M2 8a15 15 0 0 1 20 0M5 12a10 10 0 0 1 14 0m-11 4a5 5 0 0 1 8 0m-4 4h.01"/>';else if(/housing|home|rent/.test(c))path='<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>';return `<svg viewBox="0 0 24 24" aria-hidden="true">${path}</svg>`;}
function renderBudgets(){const month=$("budgetMonth").value||monthKey();const monthExpenses=state.transactions.filter(t=>t.kind==="Expense"&&inMonth(t.date,month));const spentTotal=sum(monthExpenses,t=>t.amount);const budgetTotal=sum(state.budgets,b=>Number(b.limit)||0);const pctTotal=budgetTotal?Math.min(100,spentTotal/budgetTotal*100):0;$("budgetGaugeSpent").textContent=money(spentTotal);$("budgetGaugeLimit").textContent=`of ${money(budgetTotal)}`;$("budgetGaugePercent").textContent=`${Math.round(pctTotal)}% spent`;
$("budgetGaugeRemaining").textContent=`${money(budgetTotal-spentTotal)} remaining`;$("budgetGaugeFill").style.strokeDasharray=`${Math.PI*96}`;$("budgetGaugeFill").style.strokeDashoffset=`${Math.PI*96*(1-pctTotal/100)}`;
$("budgetList").className="budget-stack"+ (state.budgets.length?"":" empty");
$("budgetList").innerHTML=state.budgets.length?state.budgets.map(b=>{const spent=sum(state.transactions.filter(t=>t.kind==="Expense"&&t.category===b.category&&inMonth(t.date,month)),t=>t.amount),pct=b.limit?spent/b.limit*100:0;return `<button type="button" class="budget-item budget-category-row" data-budget-category="${esc(b.category)}"><span class="budget-category-icon">${budgetCategoryIcon(b.category)}</span><span class="budget-category-main"><span class="budget-category-line"><strong>${esc(b.category)}</strong><span>${money(spent)} <i>/ ${money(b.limit)}</i></span></span><span class="budget-progress-line"><span class="progress"><span class="${pct>100?"over":""}" style="width:${Math.min(100,pct)}%"></span></span><b>${Math.round(pct)}%</b></span></span></button>`;}).join(""):empty("No budgets set yet.");
}

function renderReports(){
 const from=$("reportFrom")?.value||monthKey()+"-01",to=$("reportTo")?.value||new Date().toISOString().slice(0,10),account=$("reportAccount")?.value||"",type=$("reportType")?.value||"All",category=$("reportCategory")?.value||"";
 const tx=state.transactions.filter(t=>!t.isReminder&&String(t.date)>=from&&String(t.date)<=to&&(type==="All"||t.kind===type)&&(!account||String(t.accountId)===String(account))&&(!category||t.category===category));
 const inc=sum(tx.filter(t=>t.kind==="Income"),t=>t.amount),exp=sum(tx.filter(t=>t.kind==="Expense"),t=>t.amount),trans=sum(tx.filter(t=>t.kind==="Transfer"),t=>t.amount);
 $("reportIncome").textContent=money(inc);$("reportExpense").textContent=money(exp);$("reportNet").textContent=money(inc-exp);
 const incomeCats={};tx.filter(t=>t.kind==="Income").forEach(t=>incomeCats[t.category]=(incomeCats[t.category]||0)+Number(t.amount||0));
 const incomeRows=Object.entries(incomeCats).sort((a,b)=>b[1]-a[1]);
 const incomeSummary=$("reportIncomeSummary");if(incomeSummary){incomeSummary.className="list-card"+(incomeRows.length?"":" empty");incomeSummary.innerHTML=incomeRows.length?incomeRows.map(([c,v])=>`<div class="list-row"><button type="button" class="text-btn" data-income-category="${esc(c)}">${esc(c)}</button><div class="row-main"><small>${inc?Math.round(v/inc*100):0}% of income</small></div><div class="row-amount positive">${money(v)}</div></div>`).join(""):empty("No income data for this period.");}
 const cats={};tx.filter(t=>t.kind==="Expense").forEach(t=>cats[t.category]=(cats[t.category]||0)+t.amount);const rows=Object.entries(cats).sort((a,b)=>b[1]-a[1]);
 $("categoryReport").className="list-card"+(rows.length?"":" empty");$("categoryReport").innerHTML=rows.length?rows.map(([c,v])=>`<button type="button" class="list-row report-category-row" data-report-category="${esc(c)}"><div class="row-main"><strong>${esc(c)}</strong><small>${exp?Math.round(v/exp*100):0}% of spending · Tap to view transactions</small><div class="report-bar"><i style="width:${exp?Math.max(1,v/exp*100):0}%"></i></div></div><div class="row-amount">${money(v)} ›</div></button>`).join(""):empty("No spending data for this period.");
 const daily={};tx.forEach(t=>{const k=t.date||"Undated";(daily[k] ||= {inc:0,exp:0});if(t.kind==="Income")daily[k].inc+=t.amount;if(t.kind==="Expense")daily[k].exp+=t.amount;});const days=Object.entries(daily).sort((a,b)=>a[0].localeCompare(b[0])).slice(-14),max=Math.max(1,...days.flatMap(x=>[x[1].inc,x[1].exp]));
 $("reportTrend").innerHTML=days.length?`<div class="chart-legend"><span class="positive">● Income</span><span class="negative">● Expenses</span></div><div class="bar-chart">${days.map(([d,v])=>`<div class="bar-pair"><div class="bar-columns"><i class="bar-income" style="height:${v.inc/max*100}%" title="Income ${money(v.inc)}"></i><i class="bar-expense" style="height:${v.exp/max*100}%" title="Expenses ${money(v.exp)}"></i></div><small>${esc(d.slice(5))}</small></div>`).join("")}</div>`:empty("No activity in selected period.");
 const byAccount={};tx.forEach(t=>{const k=t.account||"Unassigned";(byAccount[k] ||= {inc:0,exp:0,count:0});if(t.kind==="Income")byAccount[k].inc+=t.amount;if(t.kind==="Expense")byAccount[k].exp+=t.amount;byAccount[k].count++;});const ar=Object.entries(byAccount).sort((a,b)=>(b[1].inc-b[1].exp)-(a[1].inc-a[1].exp));$("accountReport").innerHTML=ar.length?ar.map(([n,v])=>`<div class="list-row"><div class="row-main"><strong>${esc(n)}</strong><small>${v.count} entries · Net ${money(v.inc-v.exp)}</small></div><div class="row-amount">${money(v.inc+v.exp)}</div></div>`).join(""):empty("No account activity.");
 const nr=$("netWorthReport");if(nr){const ast=sum(state.assets,x=>Number(x.value)||0)+sum((state.accounts||[]).filter(a=>!a.closed),accountBalance),deb=sum(state.liabilities,x=>Number(x.value)||0),inv=sum(state.investments||[],h=>Number(h.value)||0);nr.className="list-card";nr.innerHTML=`<div class="list-row"><div class="row-main"><strong>Total assets</strong><small>Accounts, assets and investments</small></div><div class="row-amount positive">${money(ast+inv)}</div></div><div class="list-row"><div class="row-main"><strong>Liabilities</strong></div><div class="row-amount negative">${money(deb)}</div></div><div class="list-row"><div class="row-main"><strong>Net worth</strong></div><div class="row-amount">${money(ast+inv-deb)}</div></div>`;}
 $("portfolioReport").className="list-card"+(state.assets.length?"":" empty");$("portfolioReport").innerHTML=state.assets.length?state.assets.map(a=>`<div class="list-row"><div class="row-main"><strong>${esc(a.name)}</strong><small>${esc(a.assetClass)} · ${sum(state.assets,x=>x.value)?Math.round(a.value/sum(state.assets,x=>x.value)*100):0}%</small></div><div class="row-amount">${money(a.value)}</div></div>`).join(""):empty("Add assets to see allocation.");
}

$("addAccountBtn").onclick=()=>showDialog("accountDialog");
$("accountForm").onsubmit=async e=>{e.preventDefault();state.accounts.push({id:id(),name:$("accountName").value.trim(),type:$("accountType").value,openingBalance:Number($("accountOpening").value)||0,closed:false,source:"manual"});if(!(await persist()))return;$("accountDialog").close();e.target.reset();toast("Account added");};
pendingBluecoins=null;
$("bluecoinsInput").onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const data=JSON.parse(await file.text());if(data.format!=="mywealth-bluecoins-import-v1"||!Array.isArray(data.transactions)||!Array.isArray(data.accounts))throw Error("This is not a supported My Wealth export.");pendingBluecoins=data;$("bluecoinsPreview").textContent=`Ready to import ${data.transactions.length.toLocaleString("en-IN")} records, ${data.accounts.length} accounts, ${data.categories?.parents?.length||0} parent categories and ${data.categories?.children?.length||0} subcategories. Amount scale will be validated and normalized before saving.`;$("confirmBluecoinsBtn").disabled=false;}catch(err){pendingBluecoins=null;$("bluecoinsPreview").textContent="Could not read file: "+err.message;$("confirmBluecoinsBtn").disabled=true;}e.target.value="";};
$("confirmBluecoinsBtn").onclick=async()=>{if(!pendingBluecoins)return;const preview=pendingBluecoins.transactions.filter(t=>!t.isReminder);const sample=preview.find(t=>t.source?.amount!==undefined&&Number(t.source.amount)!==0);const ratio=sample?Math.abs(Number(sample.amount)/Number(sample.source.amount)):0;if(!ratio||!(Math.abs(ratio-0.01)<0.000001||Math.abs(ratio-1/1000000)<0.000000001)) {toast("Amount scale could not be validated. Import stopped.");return;}if(!confirm(`Import ${pendingBluecoins.transactions.length} source records and ${pendingBluecoins.accounts.length} account records? Amount conversion validated. This adds the full history.`))return;
 const batch="bluecoins-"+id(), existing=new Set(state.transactions.map(t=>String(t.sourceId||""))),accountMap={};
 for(const a of pendingBluecoins.accounts){if(a.accountsTableID<2)continue;let existingAcc=state.accounts.find(x=>String(x.sourceId)===String(a.accountsTableID));if(!existingAcc){existingAcc={id:id(),sourceId:String(a.accountsTableID),name:a.accountName,type:a.accountTypeID===3?"Bank":a.accountTypeID===4?"Credit card":a.accountTypeID===5?"Investment":"Other",openingBalance:0,closed:!!a.accountHidden,source:"Bluecoins",sourceBatch:batch};state.accounts.push(existingAcc);}accountMap[String(a.accountsTableID)]=existingAcc.id;}
 let added=0;const sourceRows=pendingBluecoins.transactions;const batchSize=200;
 // Commit in small durable batches. If Safari closes mid-import, already committed
 // rows remain in IndexedDB and a retry skips them by sourceId.
 for(let offset=0;offset<sourceRows.length;offset+=batchSize){
   const chunk=sourceRows.slice(offset,offset+batchSize);
   for(const t of chunk){const sid=String(t.sourceId??"");if(sid&&existing.has(sid))continue;const sourceAmount=Number(t.source?.amount??t.amount)||0;const amount=Math.abs(sourceAmount/1000000);const kind=t.type==="Transfer"?"Transfer":t.type==="Income"?"Income":"Expense";state.transactions.push({id:id(),sourceId:sid,date:String(t.date||"").slice(0,10),amount,kind,category:t.category||"Uncategorised",parentCategory:t.parentCategory||"",note:[t.description,t.notes].filter(Boolean).join(" · "),accountId:accountMap[String(t.accountId)]||null,account:t.account||"",counterAccountId:accountMap[String(t.counterAccountId)]||null,counterAccount:t.counterAccount||"",transferGroupId:t.transferGroupId||0,labels:t.labels||[],isReminder:!!t.isReminder,deletedFlag:t.deletedFlag,sourceAmountRaw:sourceAmount,sourceBatch:batch,source:"Bluecoins",amountScaleCorrected:true});if(sid)existing.add(sid);added++;}
   if(!Array.isArray(state.categories))state.categories=[];
   const importedNames=[...new Set(sourceRows.filter(x=>!x.isReminder&&x.category).map(x=>x.category))];
   for(const name of importedNames){const inferredKind=sourceRows.find(x=>x.category===name&&x.type==="Income")?"Income":"Expense";if(!state.categories.some(c=>c.name===name&&c.kind===inferredKind))state.categories.push({kind:inferredKind,name,source:"Bluecoins"});}
   state.bluecoinsMeta={categoryTree:pendingBluecoins.categories,source:pendingBluecoins.source,sourceBatch:batch,importedAt:new Date().toISOString(),sourceRecordCount:sourceRows.length,addedRecords:added,reminders:sourceRows.filter(t=>t.isReminder).length,amountScale:"source millionths divided by 1,000,000",progress:Math.min(offset+chunk.length,sourceRows.length)};
   if(!(await persist())){toast(`Import paused after ${added} records were safely saved. Select the same file and retry to continue.`);return;}
   $("bluecoinsPreview").textContent=`Saving Bluecoins history: ${Math.min(offset+chunk.length,sourceRows.length).toLocaleString("en-IN")} / ${sourceRows.length.toLocaleString("en-IN")} records…`;
 }
 state.bluecoinsMeta.completedAt=new Date().toISOString();refreshAdvancedFilters();options($("entryCategory"),getCategories(currentKind),"");options($("budgetCategory"),getCategories("Expense"),"");if(!(await persist()))return;pendingBluecoins=null;$("bluecoinsPreview").textContent=`Imported ${added.toLocaleString("en-IN")} records. Amounts normalized to INR; account links retained.`;$("confirmBluecoinsBtn").disabled=true;toast(`Imported ${added.toLocaleString("en-IN")} Bluecoins records`);};

function getCategories(kind){
 const base=kind==="Income"?INCOMES:EXPENSES;
 const raw=state.categories;
 // Bluecoins migration stores category metadata as {parents:[], children:[]};
 // user-managed categories use an array. Never call .filter on the object shape.
 const rows=Array.isArray(raw)?raw:[];
 const hidden=new Set(rows.filter(c=>c.kind===kind&&(c.deleted||c.oldName)).map(c=>c.oldName||c.name));
 const renamed=rows.filter(c=>c.kind===kind&&c.oldName&&!c.deleted).map(c=>c.name);
 const custom=rows.filter(c=>c.kind===kind&&!c.deleted&&!c.oldName).map(c=>c.name);
 const imported=(state.transactions||[]).filter(t=>t.kind===kind&&t.category&&!t.isReminder).map(t=>t.category);
 return [...new Set([...base.filter(n=>!hidden.has(n)),...renamed,...custom,...imported])].filter(Boolean).sort((a,b)=>a.localeCompare(b));
}
$("manageCategoriesBtn").onclick=()=>{renderCategoryManager();showDialog("categoryDialog");};
function renderCategoryManager(){if(!Array.isArray(state.categories))state.categories=[];const kind=$("categoryKind").value;$("categoryListEditor").innerHTML=[...getCategories(kind)].map(n=>`<div class="category-edit-row"><span>${esc(n)}</span><button type="button" class="text-btn" data-category-edit="${esc(n)}">Rename</button><button type="button" class="text-btn" data-category-delete="${esc(n)}">Delete</button></div>`).join("");document.querySelectorAll("[data-category-edit]").forEach(b=>b.onclick=async()=>{const old=b.dataset.categoryEdit,n=prompt("New category name",old);if(!n||!n.trim())return;const c=state.categories.find(x=>x.kind===kind&&x.name===old);if(c)c.name=n.trim();else state.categories.push({kind,name:n.trim(),oldName:old});state.transactions.forEach(t=>{if(t.kind===kind&&t.category===old)t.category=n.trim();});await persist();renderCategoryManager();});document.querySelectorAll("[data-category-delete]").forEach(b=>b.onclick=async()=>{const name=b.dataset.categoryDelete;if(!confirm(`Remove ${name} from category choices? Existing transactions will keep this category.`))return;state.categories.push({kind,name,deleted:true});await persist();renderCategoryManager();});}
$("categoryKind").onchange=renderCategoryManager;
$("categoryForm").onsubmit=async e=>{e.preventDefault();const kind=$("categoryKind").value,name=$("categoryName").value.trim();if(!name)return;if(getCategories(kind).some(x=>x.toLowerCase()===name.toLowerCase())){toast("Category already exists");return;}state.categories.push({kind,name});if(!(await persist()))return;$("categoryName").value="";renderCategoryManager();toast("Category added");};


function openTransactionDetail(txid){const t=state.transactions.find(x=>String(x.id)===String(txid));if(!t)return;activeDetailTransactionId=t.id;$("detailTitle").textContent=t.category||t.kind;$("transactionDetailBody").innerHTML=`<div class="detail-grid"><p><small>Date</small><strong>${esc(t.date||"—")}</strong></p><p><small>Amount</small><strong>${money(t.amount)}</strong></p><p><small>Type</small><strong>${esc(t.kind)}</strong></p><p><small>Account</small><strong>${esc(t.account||"Unassigned")}${t.kind==="Transfer"?" → "+esc(t.counterAccount||"Unassigned"):""}</strong></p><p><small>Category</small><strong>${esc(t.category||"—")}</strong></p><p><small>Description</small><strong>${esc(t.note||"—")}</strong></p></div>`;showDialog("transactionDetailDialog");}
function editOrCopyTransaction(copy=false){const t=state.transactions.find(x=>String(x.id)===String(activeDetailTransactionId));if(!t)return;editingTransactionId=copy?null:t.id;currentKind=t.kind==="Income"?"Income":t.kind==="Transfer"?"Transfer":"Expense";$("entryTitle").textContent=copy?"Copy transaction":"Edit transaction";$("saveEntryBtn").textContent=copy?"Save copy":"Save changes";$("transactionForm").reset();$("entryAmount").value=t.amount;$("entryDate").value=copy?new Date().toISOString().slice(0,10):t.date;options($("entryCategory"),getCategories(currentKind),t.category);$("entryNote").value=t.note||"";refreshAccountSelect();$("entryAccount").value=t.accountId||"";$("entryRecurring").checked=!!t.recurring;setTransactionKind(currentKind);$("entryToAccount").value=t.counterAccountId||"";$("transactionDetailDialog").close();showDialog("entryDialog");}
$("detailEditBtn").onclick=()=>editOrCopyTransaction(false);$("detailCopyBtn").onclick=()=>editOrCopyTransaction(true);$("detailDeleteBtn").onclick=async()=>{if(!activeDetailTransactionId||!confirm("Delete this transaction?"))return;state.transactions=state.transactions.filter(t=>String(t.id)!==String(activeDetailTransactionId));$("transactionDetailDialog").close();await persist();toast("Transaction deleted");};
function updateBulkToolbar(){const n=selectedTransactionIds.size;$("selectedTxCount").textContent=`${n} selected`;$("bulkToolbar").classList.toggle("has-selection",n>0);if($("selectAllTx"))$("selectAllTx").checked=n>0&&n===$$("[data-select-tx]").length;}
function $$(sel){return [...document.querySelectorAll(sel)];}
$("selectAllTx").onchange=()=>{$$("[data-select-tx]").forEach(c=>{c.checked=$("selectAllTx").checked;const k=String(c.dataset.selectTx);c.checked?selectedTransactionIds.add(k):selectedTransactionIds.delete(k);});updateBulkToolbar();};
$("deselectAllTx").onclick=()=>{selectedTransactionIds.clear();$$("[data-select-tx]").forEach(c=>c.checked=false);updateBulkToolbar();};
if($("selectAllLabel"))$("selectAllLabel").onclick=()=>{$("selectAllTx").checked=true;$("selectAllTx").dispatchEvent(new Event("change"));};
if($("bulkCategoriseBtn"))$("bulkCategoriseBtn").onclick=async()=>{if(!selectedTransactionIds.size)return;const selected=state.transactions.filter(t=>selectedTransactionIds.has(String(t.id)));const kinds=[...new Set(selected.filter(t=>t.kind!=="Transfer").map(t=>t.kind))];if(!kinds.length){toast("Transfers do not use spending categories");return;}if(kinds.length>1){toast("Select only income or only expense transactions to categorise together");return;}const kind=kinds[0],choices=getCategories(kind),chosen=prompt(`Choose a ${kind.toLowerCase()} category:\n\n${choices.map((c,i)=>`${i+1}. ${c}`).join("\n")}\n\nEnter the category name exactly:`);if(!chosen)return;if(!choices.includes(chosen.trim())){toast("That category is not in the category list");return;}selected.forEach(t=>{if(t.kind===kind)t.category=chosen.trim();});if(!(await persist()))return;selectedTransactionIds.clear();updateBulkToolbar();toast(`${selected.length} transactions categorised`);};
$("bulkDeleteBtn").onclick=async()=>{if(!selectedTransactionIds.size)return;if(!confirm(`Delete ${selectedTransactionIds.size} selected transactions?`))return;state.transactions=state.transactions.filter(t=>!selectedTransactionIds.has(String(t.id)));selectedTransactionIds.clear();await persist();updateBulkToolbar();toast("Selected transactions deleted");};
function openReportCategory(category){const from=$("reportFrom").value||monthKey()+"-01",to=$("reportTo").value||new Date().toISOString().slice(0,10),account=$("reportAccount").value||"";const rows=state.transactions.filter(t=>!t.isReminder&&t.kind==="Expense"&&t.category===category&&String(t.date)>=from&&String(t.date)<=to&&(!account||String(t.accountId)===String(account))).sort((a,b)=>String(b.date).localeCompare(String(a.date)));$("budgetTransactionsTitle").textContent=`${category} · Expenses · ${from} to ${to}`;$("budgetTransactionsList").innerHTML=`<div class="summary-strip"><span>${rows.length} transactions · Total spending</span><strong>${money(sum(rows,t=>t.amount))}</strong></div>`+(rows.length?rows.map(t=>txRow(t,false)).join(""):empty("No transactions in this category for the selected period."));showDialog("budgetTransactionsDialog");}
function openBudgetCategory(category,kind="Expense"){const month=$("budgetMonth").value||monthKey();const rows=state.transactions.filter(t=>t.kind===kind&&t.category===category&&inMonth(t.date,month)).sort((a,b)=>String(b.date).localeCompare(String(a.date)));$("budgetTransactionsTitle").textContent=`${category} · ${kind} · ${month}`;$("budgetTransactionsList").innerHTML=rows.length?rows.map(t=>txRow(t,false)).join(""):empty("No transactions for this category and month.");showDialog("budgetTransactionsDialog");}
document.addEventListener("click",e=>{const rc=e.target.closest("[data-report-category]");if(rc)openReportCategory(rc.dataset.reportCategory);const b=e.target.closest("[data-budget-category]");if(b)openBudgetCategory(b.dataset.budgetCategory,"Expense");const i=e.target.closest("[data-income-category]");if(i)openBudgetCategory(i.dataset.incomeCategory,"Income");});

