// Activity month controls and bulk actions. Month navigation filters the list without changing saved records.
let activityMonthOffset=0;
function setActivityMonth(){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+activityMonthOffset);const m=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;$("activityMonthLabel").textContent=d.toLocaleDateString("en-IN",{month:"short",year:"numeric"});activityFilters.from=m+"-01";const last=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();activityFilters.to=m+"-"+String(last).padStart(2,"0");render();}
$("activityPrevMonth").onclick=()=>{activityMonthOffset--;setActivityMonth();};$("activityNextMonth").onclick=()=>{activityMonthOffset++;setActivityMonth();};setActivityMonth();
$("bulkAddBtn").onclick=()=>$("addTransactionBtn").click();
$("bulkCopyBtn").onclick=()=>{const first=[...selectedTransactionIds][0];if(!first){toast("Select a transaction first");return;}activeDetailTransactionId=first;editOrCopyTransaction(true);};
$("bulkEditBtn").onclick=()=>{const first=[...selectedTransactionIds][0];if(!first){toast("Select a transaction first");return;}openTransactionDetail(first);};
$("settingsAccountsBtn").onclick=()=>{nav("wealth");setTimeout(()=>$("accountList").scrollIntoView({behavior:"smooth",block:"start"}),80);};
$("settingsAboutBtn").onclick=()=>toast("My Wealth · Private finance tracker");

storageReady.then(()=>{refreshAdvancedFilters();render();}).catch(()=>{});

function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
// One-time automatic correction for legacy imports that were saved 10,000x too high.
(async function repairLegacyBluecoinsAmounts(){const legacy=state.transactions.filter(t=>t.source==="Bluecoins"&&t.sourceAmountRaw!==undefined&&!t.amountScaleCorrected);if(legacy.length){legacy.forEach(t=>{t.amount=Number(t.amount)/10000;t.amountScaleCorrected=true;});if(state.bluecoinsMeta)state.bluecoinsMeta.amountScaleCorrectedAt=new Date().toISOString();await persist();}})();

$("exportCsvBtn").onclick=()=>{const rows=[["date","description","amount","type","category"],...state.transactions.filter(t=>!t.isReminder).map(t=>[t.date,t.note,t.kind==="Income"?t.amount:-t.amount,t.kind,t.category])];download("my-wealth-transactions.csv",rows.map(r=>r.map(csvCell).join(",")).join("\r\n"),"text/csv");};
function csvCell(v){return `"${String(v??"").replace(/"/g,'""')}"`;}
$("exportJsonBtn").onclick=()=>download("my-wealth-backup.json",JSON.stringify(state,null,2),"application/json");
$("restoreJsonInput").onchange=async e=>{try{const obj=JSON.parse(await e.target.files[0].text());if(!obj||!Array.isArray(obj.transactions)||!Array.isArray(obj.assets)||!Array.isArray(obj.liabilities)||!Array.isArray(obj.budgets))throw Error("Invalid backup structure");if(!confirm("Replace all current local data with this backup?"))return;state=obj;if(!(await persist()))throw Error("Could not save restored backup");toast("Backup restored");}catch(err){toast("Restore failed: "+err.message);}e.target.value="";};
$("importCsvInput").onchange=async e=>{try{const text=await e.target.files[0].text(),lines=parseCSV(text);if(lines.length<2)throw Error("No data rows found");const headers=lines[0].map(x=>x.trim().toLowerCase());const idx=k=>headers.indexOf(k);if(["date","amount","type"].some(k=>idx(k)<0))throw Error("CSV needs date, amount and type columns");let count=0;for(const row of lines.slice(1)){const amount=Number(row[idx("amount")]);if(!Number.isFinite(amount)||amount===0)continue;const rawType=(row[idx("type")]||"").toLowerCase();const kind=rawType.includes("income")||amount>0?"Income":"Expense";state.transactions.push({id:id(),date:row[idx("date")]||new Date().toISOString().slice(0,10),amount:Math.abs(amount),kind,category:idx("category")>=0&&row[idx("category")]?row[idx("category")]:"Imported",note:idx("description")>=0?row[idx("description")]:"",recurring:false});count++;}if(!(await persist()))throw Error("Could not save imported rows");toast(`Imported ${count} rows`);}catch(err){toast("Import failed: "+err.message);}e.target.value="";};
function parseCSV(text){const rows=[];let row=[],cell="",quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'&&quoted&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"'){quoted=!quoted;}else if(c===","&&!quoted){row.push(cell);cell="";}else if((c==="\n"||c==="\r")&&!quoted){if(c==="\r"&&text[i+1]==="\n")i++;row.push(cell);if(row.some(x=>x!==""))rows.push(row);row=[];cell="";}else cell+=c;}row.push(cell);if(row.some(x=>x!==""))rows.push(row);return rows;}

function config(){return JSON.parse(localStorage.getItem("mywealth-cloud")||"{}");}
function updateCloudStatus(){const c=config();$("cloudStatus").textContent=c.url&&c.key?(session?.user?.email?`Connected as ${session.user.email}`:"Configured · Sign in to sync"):"Not configured · Local-only mode";}
$("configureCloudBtn").onclick=()=>{const c=config();$("supabaseUrl").value=c.url||"";$("supabaseKey").value=c.key||"";showDialog("cloudDialog");};
$("cloudForm").onsubmit=e=>{e.preventDefault();const url=$("supabaseUrl").value.trim().replace(/\/$/,""),key=$("supabaseKey").value.trim();if(!/^https:\/\/.+\.supabase\.co$/.test(url)){toast("Enter a valid Supabase project URL");return;}localStorage.setItem("mywealth-cloud",JSON.stringify({url,key}));$("cloudDialog").close();initSupabase();updateCloudStatus();toast("Cloud configuration saved");};
async function initSupabase(){const c=config();if(!c.url||!c.key){supabase=null;return;}supabase={url:c.url,key:c.key};const token=localStorage.getItem("mywealth-token");if(token){try{const res=await sbFetch("/auth/v1/user",{method:"GET",token});if(res?.id)session={user:res,access_token:token};else{localStorage.removeItem("mywealth-token");session=null;}}catch{session=null;}}updateCloudStatus();}
async function sbFetch(path,{method="GET",body,token}={}){if(!supabase)throw Error("Configure cloud sync first");const t=token||session?.access_token||supabase.key;const r=await fetch(supabase.url+path,{method,headers:{"apikey":supabase.key,"Authorization":"Bearer "+t,"Content-Type":"application/json","Prefer":"resolution=merge-duplicates,return=minimal"},...(body!==undefined?{body:JSON.stringify(body)}:{})});const text=await r.text();if(!r.ok)throw Error(text||`Cloud error ${r.status}`);return text?JSON.parse(text):null;}
$("loginBtn").onclick=()=>showDialog("authDialog");
$("authForm").onsubmit=async e=>{e.preventDefault();try{const result=await sbFetch("/auth/v1/token?grant_type=password",{method:"POST",body:{email:$("authEmail").value,password:$("authPassword").value}});session={...result,user:result.user};localStorage.setItem("mywealth-token",result.access_token);updateCloudStatus();$("authDialog").close();toast("Signed in");await syncCloud();}catch(err){toast("Sign in failed: "+err.message);}};
$("signupBtn").onclick=async()=>{try{await sbFetch("/auth/v1/signup",{method:"POST",body:{email:$("authEmail").value,password:$("authPassword").value}});toast("Account created. Check email if confirmation is enabled.");}catch(err){toast("Sign-up failed: "+err.message);}};
$("logoutBtn").onclick=()=>{session=null;localStorage.removeItem("mywealth-token");updateCloudStatus();toast("Signed out");};
$("syncNowBtn").onclick=()=>syncCloud();
async function syncCloud(){if(!supabase){toast("Configure cloud sync first");showDialog("cloudDialog");return;}if(!session?.access_token){toast("Sign in to your cloud account first");showDialog("authDialog");return;}try{const rows=await sbFetch("/rest/v1/user_finance?select=data&id=eq."+encodeURIComponent(session.user.id));if(rows?.[0]?.data){state=mergeState(state,rows[0].data);}const payload={id:session.user.id,data:state,updated_at:new Date().toISOString()};await sbFetch("/rest/v1/user_finance?on_conflict=id",{method:"POST",body:payload});await persist();toast("Cloud sync complete");}catch(err){toast("Sync failed: "+err.message);}}
function mergeState(local,cloud){const merged=emptyState();for(const k of Object.keys(merged)){const map=new Map();[...(cloud[k]||[]),...(local[k]||[])].forEach(x=>map.set(x.id,x));merged[k]=[...map.values()];}return merged;}
$("installHelpBtn").onclick=()=>alert("On your iPhone: open this site in Safari → tap Share → Add to Home Screen → Add. Use Safari, not an in-app browser.");
$("clearDataBtn").onclick=async()=>{if(confirm("Permanently delete all local finance records on this device? This does not delete cloud records.")){state=emptyState();if(await persist())toast("Local data deleted");}};
initSupabase();

if("serviceWorker" in navigator && location.protocol.startsWith("http"))navigator.serviceWorker.register("./sw.js").catch(()=>{});
